#include <string>
#include <iostream>

class Person {
    // Поля (члены-данные) — по умолчанию private в class
    std::string name_;
    int age_;
    static int count_; // статическое поле — одно на все объекты класса

public:
    // Конструкторы — especiales функции, вызываются при создании объекта
    Person() : name_("Unknown"), age_(0) { ++count_; }           // конструктор по умолчанию
    Person(const std::string& n, int a) : name_(n), age_(a) { ++count_; } // параметризованный

    // Деструктор — вызывается при уничтожении объекта
    ~Person() { --count_; std::cout << name_ << " destroyed\n"; }

    // Методы (члены-функции)
    void print() const {           // const — обещает не менять объект
        std::cout << name_ << ", " << age_ << " лет\n";
    }

    // Геттеры и сеттеры — контролируемый доступ к полям
    const std::string& name() const { return name_; }
    void set_name(const std::string& n) { name_ = n; }
    int age() const { return age_; }
    void set_age(int a) { if (a >= 0) age_ = a; }

    // Статический метод — работает с классом, а не с конкретным объектом
    static int count() { return count_; }
};

// Определение статического поля (обычно в .cpp файле)
int Person::count_ = 0;

int main() {
    Person p1("Алиса", 25);
    Person p2("Боб", 30);
    p1.print(); // Алиса, 25 лет
    std::cout << Person::count(); // 2
}

class Point {
    int x_, y_;
public:
    // ПРАВИЛЬНО: список инициализации (прямая инициализация)
    Point(int x, int y) : x_(x), y_(y) {}

    // ПЛОХО: присваивание в теле (сначала default init, потом assign)
    // Point(int x, int y) { x_ = x; y_ = y; }

    // Для const, reference, базовых классов — ТОЛЬКО список инициализации
    const int id_;
    Point(int id, int x, int y) : id_(id), x_(x), y_(y) {}
};

class BankAccount {
    double balance_ = 0;        // private по умолчанию для class — баланс защищён
    int pin_;                   // private

protected:                      // доступно в наследниках
    std::string account_type_;

public:
    BankAccount(int pin) : pin_(pin) {}

    // Интерфейс (public API)
    bool deposit(double amount) {
        if (amount > 0) { balance_ += amount; return true; }
        return false;
    }
    bool withdraw(double amount, int pin) {
        if (pin == pin_ && amount > 0 && amount <= balance_) {
            balance_ -= amount; return true;
        }
        return false;
    }
    double balance(int pin) const { return pin == pin_ ? balance_ : -1; }
};

// struct — по умолчанию public (для простых структур данных)
struct Point { int x, y; }; // всё public

class Matrix {
    double data[4][4];
    friend std::ostream& operator<<(std::ostream&, const Matrix&); // внешняя функция
    friend class MatrixSolver; // целый класс
};

class Animal {
protected:
    std::string name_;
public:
    Animal(const std::string& n) : name_(n) {}
    virtual ~Animal() = default; // ВИРТУАЛЬНЫЙ деструктор — ОБЯЗАТЕЛЬНО для базового класса!

    virtual void speak() const { std::cout << name_ << " делает звук\n"; }
    virtual void move() const = 0; // чисто виртуальная функция — Animal становится абстрактным
};

class Dog : public Animal { // public наследование = "is-a"
    std::string breed_;
public:
    Dog(const std::string& n, const std::string& b) : Animal(n), breed_(b) {}

    // override — проверка, что мы переопределяем виртуальную функцию (C++11)
    void speak() const override { std::cout << name_ << " гавкает: Гав!\n"; }
    void move() const override { std::cout << name_ << " бежит\n"; }

    void fetch() const { std::cout << name_ << " приносит мяч\n"; }
};

class Cat : public Animal {
public:
    Cat(const std::string& n) : Animal(n) {}
    void speak() const override { std::cout << name_ << " мяукает: Мяу!\n"; }
    void move() const override { std::cout << name_ << " шагает бесшумно\n"; }
};

// Полиморфизм — одна функция работает с разными типами
void make_speak(const Animal& a) { a.speak(); } // dynamic dispatch — вызов зависит от реального типа

int main() {
    Dog dog("Барсик", "Лабрадор");
    Cat cat("Мурка");

    Animal* animals[] = {&dog, &cat};
    for (auto* a : animals) a->speak(); // вызывает Dog::speak, Cat::speak

    // Object slicing — ОПАСНО!
    // Animal a = dog; // скопируется только часть Animal!
    // Используйте указатели или ссылки для полиморфизма
}

class A { public: virtual ~A() = default; int x; };
class B : virtual public A {};   // виртуальное наследование — один подобъект A
class C : virtual public A {};
class D : public B, public C {}; // D имеет ОДИН экземпляр A

class Resource {
    int* data_;
    size_t size_;
public:
    // 1. Конструктор
    Resource(size_t n) : size_(n), data_(new int[n]) {}

    // 2. Деструктор
    ~Resource() { delete[] data_; }

    // 3. Конструктор копирования — глубокая копия
    Resource(const Resource& other) : size_(other.size_), data_(new int[other.size_]) {
        std::copy(other.data_, other.data_ + size_, data_);
    }

    // 4. Оператор присваивания копированием
    Resource& operator=(const Resource& other) {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_;
            data_ = new int[size_];
            std::copy(other.data_, other.data_ + size_, data_);
        }
        return *this;
    }

    // 5. Move конструктор (C++11) — забираем ресурс
    Resource(Resource&& other) noexcept : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr; other.size_ = 0;
    }

    // 6. Move присваивание (C++11)
    Resource& operator=(Resource&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_; size_ = other.size_;
            other.data_ = nullptr; other.size_ = 0;
        }
        return *this;
    }
};

// Rule of Zero: если используете RAII типы (std::vector, std::unique_ptr, std::string),
// не пишите специальные функции вручную — компилятор сгенерирует правильные версии!
class ModernResource {
    std::vector<int> data_; // само управляет памятью
    // Не нужно объявлять ~ModernResource, copy, move — всё работает автоматически!
};

class Base {
public:
    virtual void foo() {}
    virtual void bar() final {} // нельзя переопределять в наследниках
};

class Derived : public Base {
public:
    void foo() override {} // OK — явно переопределяем виртуальную функцию
    // void bar() override {} // ОШИБКА: bar помечен final в базовом классе
};

